// The 100-step command guide. Single source of truth for /guide, /guide/[chapter],
// lesson pages, search and docs/GUIDE.md (generated by scripts/generate-guide-doc.mjs).
// Every command here was checked against `git <cmd> -h` / `gh <cmd> --help` (git 2.55, gh 2.98).

export type ChapterSlug =
  | "setup"
  | "first-repository"
  | "daily-loop"
  | "ignore-and-inspect"
  | "branching"
  | "github-remote"
  | "pull-requests"
  | "conflicts-and-undo"
  | "advanced-history"
  | "releases-ci-security";

export type Chapter = {
  slug: ChapterSlug;
  n: number;
  title: string;
  summary: string;
  level: "Beginner" | "Intermediate" | "Advanced" | "Pro Max";
};

export type GuideStep = {
  id: number;
  chapter: ChapterSlug;
  lesson: number;
  title: string;
  command: string;
  explain: string;
  tip?: string;
  danger?: string;
  output?: string;
};

